def init_worker(readDataMatrix=True, matrixPath="Matrices/5GThirdRate.mat"):
    global _workerCODEC
    absPath = os.path.abspath(matrixPath)
    print(f"Initialise Worker: {os.getpid()}, readDataMatrix={readDataMatrix}, matrixPath={absPath}")
    _workerCODEC =  bpsk.LDPCEncoder(4,5,2000, readDataMatrix=True, matrixPath="Matrices/BG2.mat")


def singleWorker(args):
    useInterleave = args
    global _workerCODEC
    VC = _workerCODEC
    avgSumProdBER = 0
    avgBitFlipBER = 0
    frameErrors = 0
    iterations = 0
    codeLength = 19968
    accumulateErrors = np.zeros(codeLength)
    totalFrameBitErrors = 0
    failedBitErrors = 0
    if useInterleave:
        message = np.random.randint(0, 2, size=VC.G.shape[1]).tolist()  
        
        VC.encode(message, 100)
        encoded = VC.originalEncoded
        interleavedEncoded = interleave(encoded)
        transmission = burstTransmission(interleavedEncoded, DISTRIBUTIONS, 200, harsh=True)
        # assert (np.array_equal(VC.originalEncoded, deinterleave(interleavedEncoded))), "INTERLEAVE FAILED"
        print(f"Begin Decoding... Encoded Length = {len(encoded)}")
        hardDecisions = mapConstellationsToBits(transmission)
        # compareOriginalToHardDecisions(virtualChannel.originalEncoded, deinterleave(hardDecisions.copy()),transmission)
        BER = VC.virtualSumProduct(cp.array(transmission), cp.array(deinterleave(hardDecisions)), useInterleave)
        # BER = VC.virtualSumProduct(transmission, deinterleave(hardDecisions), useInterleave)
        print(VC.originalEncoded[:80])
    else:
        os.system("cls")
        message = np.random.randint(0, 2, size=VC.G.shape[1]).tolist()  
        VC.encode(message, 100)
        encoded = VC.originalEncoded
        transmission = cp.array(burstTransmission(encoded, DISTRIBUTIONS, 200, harsh=True))
        hardDecisions = cp.array(mapConstellationsToBits(transmission))
        # compareOriginalToHardDecisions(encoded, hardDecisions,transmission)
        BER = VC.virtualSumProduct(transmission, hardDecisions, useInterleave)
    if BER == FRAME_ERROR: 
        return 1
    return float(BER)

def batchMonteCarlo(maxErrors=500, poolSize=2, useInterleave=True):
    frameErrors = 0
    iterations = 0
    BERS = []
    with Pool(processes=poolSize, initializer=init_worker) as pool:

        while frameErrors < maxErrors:
            args = [useInterleave] * poolSize
            batchResults = pool.map(singleWorker, args)
            for val in batchResults:
                if val == FRAME_ERROR: 
                    frameErrors+=1
                else: 
                    BERS.append(val)
            iterations +=1
            print(f"Batch No: {iterations}, Frame Errors: {frameErrors}, FER: {frameErrors/(iterations*poolSize)}")
            
            
    FER = frameErrors/(iterations*poolSize)
    successfulBER = BERS/iterations #check BER even when parity checks pass
    return FER, successfulBER
